var doc = Document;
// Goal: keep the run's work on disk under a new name, or throw it away and close.
// Needs execute_script { "confirm_lifecycle_actions": true }: SaveAs and Close act
// outside the transaction that rolls a failed script back, so they are gated
// (skill.md "What needs your confirmation"). Demonstrated on two scratch documents
// so the user's own model is untouched; the same calls work on `doc`.

// 1. KEEP then SAVE AS. Write, then Settle(keep: true): the group ends and the writes
//    become permanent (notice document-settled-kept). Only now does Revit allow SaveAs.
var keepDoc = Connector.CreateProjectDocument();
System.Console.WriteLine("cleanup-title=" + keepDoc.Title + ";");
Connector.WithTransaction(keepDoc, () => { Autodesk.Revit.DB.Level.Create(keepDoc, 21.0); });
Connector.Settle(keepDoc, true);

// 2. Save under the connector's exports directory (a path the user can fetch; never a
//    project path typed by hand). After SaveAs the document's Title is the file's
//    basename -- look it up by the NEW title afterwards.
var savedPath = System.IO.Path.Combine(Connector.ExportsDirectory, "howto-settle-saveas-" + System.DateTime.UtcNow.Ticks + ".rvt");
keepDoc.SaveAs(savedPath);
System.Console.WriteLine("cleanup-title=" + keepDoc.Title + ";");
bool fileExists = System.IO.File.Exists(savedPath);
string titleAfterSaveAs = keepDoc.Title;

// 3. A settled document is still readable and can be written again in a new block
//    (a fresh group opens on the next write); here just close it, then remove the
//    probe file so the exports folder does not fill up.
keepDoc.Close(false);
try { System.IO.File.Delete(savedPath); } catch { }

// 4. DISCARD then CLOSE. Settle(keep: false) rolls the group back (notice
//    document-settled-discarded); the run's `mutations` report leaves this document
//    out entirely. Close(false) then closes without a save prompt.
var discardDoc = Connector.CreateProjectDocument();
System.Console.WriteLine("cleanup-title=" + discardDoc.Title + ";");
Connector.WithTransaction(discardDoc, () => { Autodesk.Revit.DB.Level.Create(discardDoc, 22.0); });
string discardTitle = discardDoc.Title; // read BEFORE Close: a closed Document's members all throw
Connector.Settle(discardDoc, false);
discardDoc.Close(false);

// 5. Verify: the saved file existed before deletion, both scratch documents are gone.
int open = 0;
foreach (Autodesk.Revit.DB.Document d in UIApplication.Application.Documents) {
  if (d.Title == titleAfterSaveAs || d.Title == discardTitle) open++;
}
// On the user's own model the shape is: writes -> Connector.Settle(doc, true) ->
// doc.SaveAs(path) (or doc.Save()) -- and Close only when the user asked for it.
return new { fileExists, titleAfterSaveAs, scratchStillOpen = open };
